{
  "гриб": "Amanita pantherina (пантерный мухомор)",
  "состав": [
    {
      "вещество": "Изоботеновая кислота (ibotenic acid)",
      "содержание": "0,1–1,3 % от свежего веса (типично ≈ 0,5 %)",
      "влияние": "Нейротоксин-агонист глутаматных рецепторов, вызывает галлюцинации, тремор и судороги."
    },
    {
      "вещество": "Мусцимол (muscimol)",
      "содержание": "0,05–0,6 % от свежего веса (типично ≈ 0,2 %)",
      "влияние": "Агонист GABA-A рецепторов, вызывает седацию, сонливость и лёгкие миалгические галлюцинации."
    },
    {
      "вещество": "γ-Аминомасляная кислота (GABA)",
      "содержание": "до ≈ 0,1 % от свежего веса",
      "влияние": "Эндогенный тормозной нейромедиатор, усиливает седативный эффект мусцимола."
    },
    {
      "вещество": "Хитин (полисахарид клеточных стенок)",
      "содержание": "1–3 % от сухого веса",
      "влияние": "Белково-углеводный полимер, плохо усваивается человеком и может раздражать слизистую ЖКТ."
    },
    {
      "вещество": "Свободные аминокислоты (глутамат, аланин, лейцин и др.)",
      "содержание": "≈ 10–20 % от сухого веса",
      "влияние": "Поступают в кровь после пищеварения; глутамат в высоких дозах может усугублять нейровозбуждение."
    }
  ]
}

{
  "гриб": "Amanita citrina (лимонный мухомор / поганковидный)",
  "состав": [
    {
      "вещество": "Мани́тол",
      "содержание": "10–20 % от сухого веса",
      "влияние": "Сахарный спирт, обеспечивает энергетический запас и осмотическую регуляцию; сам по себе не токсичен."
    },
    {
      "вещество": "Трегалоза",
      "содержание": "5–15 % от сухого веса",
      "влияние": "Запасной углевод, метаболизируется до глюкозы и фруктозы в кишечнике; без специфического токсического действия."
    },
    {
      "вещество": "Эргостерол (D7-стерол)",
      "содержание": "0,5–1,5 % от сухого веса",
      "влияние": "При УФ-облучении превращается в витамин D₂; в больших дозах может вызывать лёгкое раздражение ЖКТ."
    },
    {
      "вещество": "Амани́н (пептид C₂₆H₄₁N₇O₆)",
      "содержание": "≈0,1–0,5 % от сухого веса",
      "влияние": "Слабый гастроинтестинальный раздражитель; вызывает лёгкое расстройство желудка при употреблении большого количества."
    },
    {
      "вещество": "α-Аманитин (8,16-дегидро-8,16-метаногептациклический цикл, C₃₈H₆₀N₈O₁₀S)",
      "содержание": "неизвестно (следовые количества, < 0,1 % от сухого веса)",
      "влияние": "Ингибирует РНК-полимеразу II печени; в следовых дозах A. citrina клинически значимой токсичности, как правило, не вызывает."
    },
    {
      "вещество": "Уриди́н",
      "содержание": "0,1–0,3 % от сухого веса",
      "влияние": "Нуклеотид, участвующий в синтезе РНК; сам по себе нетоксичен, но при нарушении метаболизма может способствовать кристаллурии мочевой кислоты."
    },
    {
      "вещество": "Лимонная кислота",
      "содержание": "0,5–2 % от сухого веса",
      "влияние": "Обеспечивает характерную кислинку вкуса; в умеренных количествах благоприятно влияет на пищеварение."
    },
    {
      "вещество": "Биогенные амины (гистамин, тирамин, путресцин)",
      "содержание": "неизвестно (десятки–сотни мг/кг сухого вещества)",
      "влияние": "Могут вызывать лёгкую аллергическую реакцию, головную боль или умеренное расстройство ЖКТ при индивидуальной чувствительности."
    },
    {
      "вещество": "Каротиноидные пигменты (предположительно ликопин / xantophyllы)",
      "содержание": "неизвестно (мг/кг сухого вещества)",
      "влияние": "Обеспечивают лимонно-жёлтую окраску шляпки и покрывала; выполняют антиоксидантную функцию."
    },
    {
      "вещество": "Водорастворимые белки и аминокислоты (аланин, глутамат, аспарагин)",
      "содержание": "15–25 % от сухого веса (в сумме)",
      "влияние": "Источник питательных веществ; глутамат придаёт вкус умами, в обычных дозах нетоксичен."
    }
  ]
}

{
  "гриб": "Мухомор вонючий (Amanita virosa)",
  "состав": [
    {
      "вещество": "α-аматин (α-amanitin)",
      "содержание": "~2 % от сухого веса",
      "влияние": "Специфически ингибирует RNA-полимеразу II, блокируя синтез белка и вызывая гибель клеток печени и почек."
    },
    {
      "вещество": "β-аматин (β-amanitin)",
      "содержание": "~0,3 % от сухого веса",
      "влияние": "Ингибирует RNA-полимеразы I и III, усиливая цитотоксическое действие α-аматина."
    },
    {
      "вещество": "Амануллин (amanullin)",
      "содержание": "~0,2 % от сухого веса",
      "влияние": "Практически нетоксичен; слабо связывается с RNA-полимеразой, внося малый вклад в общую токсичность."
    },
    {
      "вещество": "Виренин (virenine)",
      "содержание": "неизвестно (следовые количества, специфичен для A. virosa)",
      "влияние": "Специфический циклопентановый метаболит вида; его точное физиологическое действие на человека изучено недостаточно."
    },
    {
      "вещество": "Маннит (mannitol)",
      "содержание": "~8 % от сухого веса",
      "влияние": "Осмотически активный полиол; при массовой интоксикации может усиливать осмотический диурез и потерю электролитов."
    },
    {
      "вещество": "Тrehалоза (trehalose)",
      "содержание": "~7 % от сухого веса",
      "влияние": "Запасающий дисахарид; сам по себе нетоксичен, но расщепляется в кишечнике до глюкозы и фруктозы."
    }
  ]
}
